/* Branch -> Floor procedures. Install after 01_CreateTables.sql and 02_CreateIndexes.sql. */
IF OBJECT_ID('dbo.usp_HK_GetModuleData','P') IS NOT NULL DROP PROCEDURE dbo.usp_HK_GetModuleData;
GO
CREATE PROCEDURE dbo.usp_HK_GetModuleData @Module varchar(40), @EmployeeID int, @Filters xml=NULL AS
BEGIN
 SET NOCOUNT ON;
 DECLARE @FromDate date=CONVERT(date,NULLIF(@Filters.value('string((/Filters/FromDate)[1])','varchar(30)'),''),23),
         @ToDate date=CONVERT(date,NULLIF(@Filters.value('string((/Filters/ToDate)[1])','varchar(30)'),''),23),
         @BranchID int=CONVERT(int,NULLIF(@Filters.value('string((/Filters/BranchID)[1])','varchar(30)'),'')),
         @FloorID int=CONVERT(int,NULLIF(@Filters.value('string((/Filters/FloorID)[1])','varchar(30)'),'')),
         @StaffID int=CONVERT(int,NULLIF(@Filters.value('string((/Filters/StaffID)[1])','varchar(30)'),'')),
         @VendorID int=CONVERT(int,NULLIF(@Filters.value('string((/Filters/VendorID)[1])','varchar(30)'),'')),
         @Status varchar(20)=NULLIF(@Filters.value('string((/Filters/Status)[1])','varchar(20)'), '');
 IF @Module='Floors'
  SELECT f.FloorID,f.BranchID,b.BranchName,f.FloorNumber,f.FloorName,f.Description,f.IsActive FROM dbo.HK_FloorMaster f LEFT JOIN dbo.Branch b ON b.BranchID=f.BranchID ORDER BY b.BranchName,f.FloorNumber;
 ELSE IF @Module='Vendors'
  SELECT VendorID,VendorName,ContactPerson,ContactNumber,Email,ContractStartDate,ContractEndDate,ContractedManpower,SLARequirements,MonthlyContractCost,IsActive FROM dbo.HK_VendorMaster ORDER BY VendorName;
 ELSE IF @Module='Staff'
  SELECT s.StaffID,s.StaffCode,s.StaffName,s.EmployeeID,s.MobileNumber,s.StaffType,s.VendorID,v.VendorName,s.BranchID,b.BranchName,s.FloorID,f.FloorName,s.SupervisorID,s.ShiftName,s.JoiningDate,s.IsActive FROM dbo.HK_StaffMaster s LEFT JOIN dbo.HK_VendorMaster v ON v.VendorID=s.VendorID LEFT JOIN dbo.Branch b ON b.BranchID=s.BranchID LEFT JOIN dbo.HK_FloorMaster f ON f.FloorID=s.FloorID ORDER BY s.StaffName;
 ELSE IF @Module='Activities'
  SELECT ActivityID,ActivityName,ActivityCategory,Description,Frequency,EstimatedMinutes,Priority,RequiresInspection,RequiresPhoto,IsActive FROM dbo.HK_ActivityMaster ORDER BY ActivityName;
 ELSE IF @Module='Schedules'
  SELECT s.ScheduleID,s.ScheduleDate,s.ActivityID,a.ActivityName,s.BranchID,b.BranchName,s.FloorID,f.FloorName,s.StaffID,st.StaffName,s.SupervisorID,s.StartTime,s.EndTime,s.Frequency,s.Priority,aa.Status FROM dbo.HK_ActivitySchedule s JOIN dbo.HK_ActivityMaster a ON a.ActivityID=s.ActivityID LEFT JOIN dbo.Branch b ON b.BranchID=s.BranchID JOIN dbo.HK_FloorMaster f ON f.FloorID=s.FloorID JOIN dbo.HK_StaffMaster st ON st.StaffID=s.StaffID LEFT JOIN dbo.HK_ActivityAssignment aa ON aa.ScheduleID=s.ScheduleID WHERE s.IsActive=1 ORDER BY s.ScheduleDate DESC;
 ELSE IF @Module='Attendance'
  SELECT a.AttendanceID,a.AttendanceDate,a.StaffID,s.StaffName,a.VendorID,v.VendorName,a.BranchID,b.BranchName,a.FloorID,f.FloorName,a.ShiftName,a.LoginTime,a.LogoutTime,a.WorkingHours,a.AttendanceStatus,a.IsLate,a.IsEarlyDeparture,a.OvertimeHours,a.Remarks FROM dbo.HK_StaffAttendance a JOIN dbo.HK_StaffMaster s ON s.StaffID=a.StaffID LEFT JOIN dbo.HK_VendorMaster v ON v.VendorID=a.VendorID LEFT JOIN dbo.Branch b ON b.BranchID=a.BranchID LEFT JOIN dbo.HK_FloorMaster f ON f.FloorID=a.FloorID WHERE (@FromDate IS NULL OR a.AttendanceDate>=@FromDate) AND (@ToDate IS NULL OR a.AttendanceDate<DATEADD(day,1,@ToDate)) AND (@BranchID IS NULL OR a.BranchID=@BranchID) AND (@FloorID IS NULL OR a.FloorID=@FloorID) AND (@StaffID IS NULL OR a.StaffID=@StaffID) AND (@VendorID IS NULL OR a.VendorID=@VendorID) AND (@Status IS NULL OR a.AttendanceStatus=@Status) ORDER BY a.AttendanceDate DESC;
 ELSE IF @Module IN('DailyActivities','WeeklyMonthlyActivities','DashboardDetails','ConsolidatedReport')
 BEGIN
  IF @Module='DashboardDetails'
   SELECT (SELECT COUNT(*) FROM dbo.HK_StaffMaster WHERE IsActive=1 AND (@BranchID IS NULL OR BranchID=@BranchID)) TotalStaff,(SELECT COUNT(*) FROM dbo.HK_StaffAttendance WHERE AttendanceDate=CONVERT(date,GETDATE()) AND AttendanceStatus='Present' AND (@BranchID IS NULL OR BranchID=@BranchID)) PresentStaff,(SELECT COUNT(*) FROM dbo.HK_StaffAttendance WHERE AttendanceDate=CONVERT(date,GETDATE()) AND AttendanceStatus='Absent' AND (@BranchID IS NULL OR BranchID=@BranchID)) AbsentStaff,COUNT(*) Scheduled,SUM(CASE WHEN aa.Status IN('Completed','Verified') THEN 1 ELSE 0 END) Completed,SUM(CASE WHEN aa.Status='Pending' THEN 1 ELSE 0 END) Pending,SUM(CASE WHEN aa.Status IN('Pending','In Progress') AND aa.ScheduledDate<CONVERT(date,GETDATE()) THEN 1 ELSE 0 END) Overdue,SUM(CASE WHEN aa.Status='Rejected' THEN 1 ELSE 0 END) Rejected,CAST(100.0*SUM(CASE WHEN aa.Status IN('Completed','Verified') THEN 1 ELSE 0 END)/NULLIF(COUNT(*),0) AS decimal(5,2)) CompletionPercent,(SELECT COUNT(*) FROM dbo.HK_ActivityAssignment x JOIN dbo.HK_ActivityMaster m ON m.ActivityID=x.ActivityID WHERE m.RequiresInspection=1 AND x.Status='Completed') PendingInspections,(SELECT COUNT(*) FROM dbo.HK_Complaint WHERE Status NOT IN('Closed','Resolved') AND (@BranchID IS NULL OR BranchID=@BranchID)) OpenComplaints,ISNULL((SELECT AVG(OverallScore) FROM dbo.HK_VendorEvaluation),0) VendorScore FROM dbo.HK_ActivityAssignment aa WHERE aa.ScheduledDate>=ISNULL(@FromDate,DATEADD(day,-30,CONVERT(date,GETDATE()))) AND aa.ScheduledDate<DATEADD(day,1,ISNULL(@ToDate,CONVERT(date,GETDATE()))) AND (@BranchID IS NULL OR aa.BranchID=@BranchID) AND (@FloorID IS NULL OR aa.FloorID=@FloorID) AND (@StaffID IS NULL OR aa.StaffID=@StaffID) AND (@VendorID IS NULL OR aa.VendorID=@VendorID) AND (@Status IS NULL OR aa.Status=@Status);
  ELSE SELECT aa.AssignmentID,aa.ScheduledDate,b.BranchName,f.FloorName,a.ActivityName,s.StaffName,v.VendorName,aa.ScheduledStart,aa.ActualStart,aa.ActualEnd,aa.Status,aa.Remarks,a.Frequency,(SELECT TOP 1 ix.InspectionStatus FROM dbo.HK_Inspection ix WHERE ix.AssignmentID=aa.AssignmentID ORDER BY ix.InspectionDate DESC) InspectionStatus,CASE WHEN aa.ScheduledEnd IS NULL THEN 0 ELSE DATEDIFF(hour,CONVERT(datetime,aa.ScheduledDate)+CONVERT(datetime,aa.ScheduledEnd),ISNULL(aa.ActualEnd,GETDATE())) END DelayHours,aa.SupervisorID,aa.ActivityID,aa.FloorID,aa.StaffID FROM dbo.HK_ActivityAssignment aa LEFT JOIN dbo.Branch b ON b.BranchID=aa.BranchID JOIN dbo.HK_FloorMaster f ON f.FloorID=aa.FloorID JOIN dbo.HK_ActivityMaster a ON a.ActivityID=aa.ActivityID JOIN dbo.HK_StaffMaster s ON s.StaffID=aa.StaffID LEFT JOIN dbo.HK_VendorMaster v ON v.VendorID=aa.VendorID WHERE aa.IsActive=1 AND (@Module='DailyActivities' AND a.Frequency='Daily' OR @Module='WeeklyMonthlyActivities' AND a.Frequency IN('Weekly','Monthly') OR @Module='ConsolidatedReport') AND (@FromDate IS NULL OR aa.ScheduledDate>=@FromDate) AND (@ToDate IS NULL OR aa.ScheduledDate<DATEADD(day,1,@ToDate)) AND (@BranchID IS NULL OR aa.BranchID=@BranchID) AND (@FloorID IS NULL OR aa.FloorID=@FloorID) AND (@StaffID IS NULL OR aa.StaffID=@StaffID) AND (@VendorID IS NULL OR aa.VendorID=@VendorID) AND (@Status IS NULL OR aa.Status=@Status) ORDER BY aa.ScheduledDate DESC;
 END
 ELSE IF @Module='Inspections'
  SELECT i.InspectionID,i.AssignmentID,i.InspectionDate,a.ActivityName,b.BranchName,f.FloorName,s.StaffName,sp.Code+' : '+sp.Firstname+' '+sp.LastName SupervisorName,i.CleanlinessRating,i.QualityRating,i.InspectionStatus,i.ReworkRequired,i.Remarks FROM dbo.HK_Inspection i JOIN dbo.HK_ActivityAssignment x ON x.AssignmentID=i.AssignmentID JOIN dbo.HK_ActivityMaster a ON a.ActivityID=x.ActivityID LEFT JOIN dbo.Branch b ON b.BranchID=x.BranchID JOIN dbo.HK_FloorMaster f ON f.FloorID=x.FloorID JOIN dbo.HK_StaffMaster s ON s.StaffID=i.StaffID JOIN dbo.EmployeeInfo sp ON sp.EmployeeID=i.SupervisorID ORDER BY i.InspectionDate DESC;
 ELSE IF @Module='Complaints'
  SELECT c.ComplaintID,c.ComplaintNo,c.ComplaintDate,c.BranchID,b.BranchName,c.FloorID,f.FloorName,c.Category,c.Description,c.Priority,c.AssignedStaffID,s.StaffName AssignedStaffName,c.VendorID,v.VendorName,c.ExpectedResolution,c.Status,c.ResolutionRemarks FROM dbo.HK_Complaint c LEFT JOIN dbo.Branch b ON b.BranchID=c.BranchID LEFT JOIN dbo.HK_FloorMaster f ON f.FloorID=c.FloorID LEFT JOIN dbo.HK_StaffMaster s ON s.StaffID=c.AssignedStaffID LEFT JOIN dbo.HK_VendorMaster v ON v.VendorID=c.VendorID WHERE (@FromDate IS NULL OR c.ComplaintDate>=@FromDate) AND (@ToDate IS NULL OR c.ComplaintDate<DATEADD(day,1,@ToDate)) AND (@BranchID IS NULL OR c.BranchID=@BranchID) AND (@FloorID IS NULL OR c.FloorID=@FloorID) AND (@StaffID IS NULL OR c.AssignedStaffID=@StaffID) AND (@VendorID IS NULL OR c.VendorID=@VendorID) AND (@Status IS NULL OR c.Status=@Status) ORDER BY c.ComplaintDate DESC;
 ELSE IF @Module='VendorPerformance'
  SELECT e.EvaluationID,e.VendorID,v.VendorName,e.EvaluationYear,e.EvaluationMonth,e.ManpowerScore,e.CompletionScore,e.QualityScore,e.SlaScore,e.ComplaintScore,e.OverallScore,e.Rating,e.Remarks FROM dbo.HK_VendorEvaluation e JOIN dbo.HK_VendorMaster v ON v.VendorID=e.VendorID ORDER BY e.EvaluationYear DESC,e.EvaluationMonth DESC;
 ELSE IF @Module='Inventory'
  SELECT t.TransactionID,t.TransactionDate,t.ConsumableID,m.ItemName,t.TransactionType,t.Quantity,m.UnitOfMeasure,t.VendorID,v.VendorName,t.StaffID,s.StaffName,t.BranchID,b.BranchName,t.FloorID,f.FloorName,(SELECT SUM(CASE WHEN z.TransactionType='In' THEN z.Quantity ELSE -z.Quantity END) FROM dbo.HK_ConsumableTransaction z WHERE z.ConsumableID=t.ConsumableID) StockBalance,t.Remarks FROM dbo.HK_ConsumableTransaction t JOIN dbo.HK_ConsumableMaster m ON m.ConsumableID=t.ConsumableID LEFT JOIN dbo.HK_VendorMaster v ON v.VendorID=t.VendorID LEFT JOIN dbo.HK_StaffMaster s ON s.StaffID=t.StaffID LEFT JOIN dbo.Branch b ON b.BranchID=t.BranchID LEFT JOIN dbo.HK_FloorMaster f ON f.FloorID=t.FloorID ORDER BY t.TransactionDate DESC;
 ELSE IF @Module='Consumables'
  SELECT ConsumableID,ItemCode,ItemName,UnitOfMeasure,MinimumStock,IsActive FROM dbo.HK_ConsumableMaster ORDER BY ItemName;
 ELSE IF @Module='StaffPerformance'
  SELECT s.StaffID,s.StaffName,v.VendorName,COUNT(a.AssignmentID) AssignedTasks,SUM(CASE WHEN a.Status IN('Completed','Verified') THEN 1 ELSE 0 END) CompletedTasks,SUM(CASE WHEN a.Status='Verified' THEN 1 ELSE 0 END) OnTimeTasks,SUM(CASE WHEN a.Status IN('Pending','In Progress') THEN 1 ELSE 0 END) PendingTasks,SUM(CASE WHEN a.Status='Rejected' THEN 1 ELSE 0 END) RejectedTasks,SUM(CASE WHEN a.Status='Rework Required' THEN 1 ELSE 0 END) ReworkCount,ISNULL(AVG(CASE WHEN at.AttendanceStatus='Present' THEN 100.0 ELSE 0 END),0) AttendancePercent,ISNULL(AVG(CONVERT(decimal(5,2),i.QualityRating)),0) InspectionRating,ISNULL(AVG(CONVERT(decimal(5,2),i.QualityRating))*20,0) OverallScore FROM dbo.HK_StaffMaster s LEFT JOIN dbo.HK_VendorMaster v ON v.VendorID=s.VendorID LEFT JOIN dbo.HK_ActivityAssignment a ON a.StaffID=s.StaffID LEFT JOIN dbo.HK_StaffAttendance at ON at.StaffID=s.StaffID AND at.AttendanceDate>=DATEADD(day,-30,CONVERT(date,GETDATE())) LEFT JOIN dbo.HK_Inspection i ON i.StaffID=s.StaffID AND i.InspectionDate>=DATEADD(day,-30,GETDATE()) GROUP BY s.StaffID,s.StaffName,v.VendorName;
 ELSE RAISERROR('Unsupported Housekeeping module.',16,1);
END
GO
IF OBJECT_ID('dbo.usp_HK_GetLookups','P') IS NOT NULL DROP PROCEDURE dbo.usp_HK_GetLookups;
GO
CREATE PROCEDURE dbo.usp_HK_GetLookups @EmployeeID int AS
BEGIN SET NOCOUNT ON;
 SELECT f.FloorID,f.FloorName,f.BranchID FROM dbo.HK_FloorMaster f WHERE f.IsActive=1 ORDER BY f.FloorNumber;
 SELECT StaffID,StaffName FROM dbo.HK_StaffMaster WHERE IsActive=1 ORDER BY StaffName;
 SELECT VendorID,VendorName FROM dbo.HK_VendorMaster WHERE IsActive=1 ORDER BY VendorName;
 SELECT ActivityID,ActivityName FROM dbo.HK_ActivityMaster WHERE IsActive=1 ORDER BY ActivityName;
 SELECT aa.AssignmentID,a.ActivityName FROM dbo.HK_ActivityAssignment aa JOIN dbo.HK_ActivityMaster a ON a.ActivityID=aa.ActivityID WHERE aa.IsActive=1 AND a.IsActive=1 ORDER BY aa.AssignmentID;
 SELECT ConsumableID,ItemName FROM dbo.HK_ConsumableMaster WHERE IsActive=1 ORDER BY ItemName;
END
GO
IF OBJECT_ID('dbo.usp_HK_SaveModuleData','P') IS NOT NULL DROP PROCEDURE dbo.usp_HK_SaveModuleData;
GO
CREATE PROCEDURE dbo.usp_HK_SaveModuleData @Module varchar(40),@Payload xml,@EmployeeID int AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 DECLARE @ID int=0,@BranchID int,@FloorID int,@I1 int,@I2 int,@I3 int,@I4 int,@SupervisorEmployeeID bigint,@N1 nvarchar(2000),@N2 nvarchar(2000),@N3 nvarchar(2000),@N4 nvarchar(2000),@N5 nvarchar(2000),@N6 nvarchar(2000),@N7 nvarchar(2000),@N8 nvarchar(2000),@B1 bit,@B2 bit,@D1 decimal(12,2);
 BEGIN TRY BEGIN TRANSACTION;
 IF @Module='Floors'
 BEGIN
  SET @ID=ISNULL(@Payload.value('string((/Root/FloorID)[1])','int'),0); SET @BranchID=@Payload.value('string((/Root/BranchID)[1])','int'); SET @I1=@Payload.value('string((/Root/FloorNumber)[1])','int'); SET @N1=@Payload.value('string((/Root/FloorName)[1])','nvarchar(100)'); SET @N2=NULLIF(@Payload.value('string((/Root/Description)[1])','nvarchar(500)'),''); SET @B1=ISNULL(@Payload.value('string((/Root/IsActive)[1])','bit'),1);
  IF @BranchID IS NULL OR NOT EXISTS(SELECT 1 FROM dbo.Branch WHERE BranchID=@BranchID) RAISERROR('Select a valid branch (Location).',16,1);
  IF @I1 IS NULL OR @I1<0 OR NULLIF(LTRIM(RTRIM(@N1)),'') IS NULL RAISERROR('Floor number and name are required.',16,1);
  IF EXISTS(SELECT 1 FROM dbo.HK_FloorMaster WHERE BranchID=@BranchID AND FloorID<>@ID AND (FloorNumber=@I1 OR FloorName=@N1)) RAISERROR('A floor with this number or name already exists in this branch.',16,1);
  IF @ID=0 INSERT dbo.HK_FloorMaster(BranchID,FloorNumber,FloorName,Description,IsActive,AddedBy) VALUES(@BranchID,@I1,@N1,@N2,@B1,@EmployeeID);
  ELSE UPDATE dbo.HK_FloorMaster SET BranchID=@BranchID,FloorNumber=@I1,FloorName=@N1,Description=@N2,IsActive=@B1,UpdatedBy=@EmployeeID,UpdatedDate=GETDATE() WHERE FloorID=@ID;
 END
 ELSE IF @Module='Vendors'
 BEGIN SET @ID=ISNULL(@Payload.value('string((/Root/VendorID)[1])','int'),0); SET @N1=@Payload.value('string((/Root/VendorName)[1])','nvarchar(200)'); SET @N2=NULLIF(@Payload.value('string((/Root/ContactPerson)[1])','nvarchar(150)'),''); SET @N3=NULLIF(@Payload.value('string((/Root/ContactNumber)[1])','nvarchar(30)'),''); SET @N4=NULLIF(@Payload.value('string((/Root/Email)[1])','varchar(254)'),''); SET @N5=NULLIF(@Payload.value('string((/Root/ContractStartDate)[1])','varchar(10)'),''); SET @N6=NULLIF(@Payload.value('string((/Root/ContractEndDate)[1])','varchar(10)'),''); SET @I1=ISNULL(@Payload.value('string((/Root/ContractedManpower)[1])','int'),0); SET @N7=NULLIF(@Payload.value('string((/Root/SLARequirements)[1])','nvarchar(2000)'),''); SET @N8=NULLIF(@Payload.value('string((/Root/MonthlyContractCost)[1])','varchar(30)'),''); SET @B1=ISNULL(@Payload.value('string((/Root/IsActive)[1])','bit'),1); IF @ID=0 INSERT dbo.HK_VendorMaster(VendorName,ContactPerson,ContactNumber,Email,ContractStartDate,ContractEndDate,ContractedManpower,SLARequirements,MonthlyContractCost,IsActive,AddedBy) VALUES(@N1,@N2,@N3,@N4,CONVERT(date,@N5),CONVERT(date,@N6),@I1,@N7,CONVERT(decimal(18,2),@N8),@B1,@EmployeeID); ELSE UPDATE dbo.HK_VendorMaster SET VendorName=@N1,ContactPerson=@N2,ContactNumber=@N3,Email=@N4,ContractStartDate=CONVERT(date,@N5),ContractEndDate=CONVERT(date,@N6),ContractedManpower=@I1,SLARequirements=@N7,MonthlyContractCost=CONVERT(decimal(18,2),@N8),IsActive=@B1,UpdatedBy=@EmployeeID,UpdatedDate=GETDATE() WHERE VendorID=@ID; END
 ELSE IF @Module='Staff'
 BEGIN SET @ID=ISNULL(@Payload.value('string((/Root/StaffID)[1])','int'),0); SET @N1=@Payload.value('string((/Root/StaffCode)[1])','varchar(40)'); SET @N2=@Payload.value('string((/Root/StaffName)[1])','nvarchar(150)'); SET @I1=NULLIF(@Payload.value('string((/Root/EmployeeID)[1])','varchar(20)'),''); SET @N3=NULLIF(@Payload.value('string((/Root/MobileNumber)[1])','varchar(30)'),''); SET @N4=@Payload.value('string((/Root/StaffType)[1])','varchar(10)'); SET @I2=NULLIF(@Payload.value('string((/Root/VendorID)[1])','varchar(20)'),''); SET @BranchID=NULLIF(@Payload.value('string((/Root/BranchID)[1])','varchar(20)'),''); SET @FloorID=NULLIF(@Payload.value('string((/Root/FloorID)[1])','varchar(20)'),''); SET @SupervisorEmployeeID=NULLIF(@Payload.value('string((/Root/SupervisorID)[1])','varchar(20)'),''); SET @N5=NULLIF(@Payload.value('string((/Root/ShiftName)[1])','nvarchar(50)'),''); SET @N6=NULLIF(@Payload.value('string((/Root/JoiningDate)[1])','varchar(10)'),''); SET @B1=ISNULL(@Payload.value('string((/Root/IsActive)[1])','bit'),1); IF @SupervisorEmployeeID IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.EmployeeInfo WHERE EmployeeID=@SupervisorEmployeeID) RAISERROR('Select a valid supervisor.',16,1); IF @BranchID IS NOT NULL AND @FloorID IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.HK_FloorMaster WHERE FloorID=CONVERT(int,@FloorID) AND BranchID=CONVERT(int,@BranchID)) RAISERROR('The selected floor does not belong to the selected branch.',16,1); IF @ID=0 INSERT dbo.HK_StaffMaster(StaffCode,StaffName,EmployeeID,MobileNumber,StaffType,VendorID,BranchID,FloorID,SupervisorID,ShiftName,JoiningDate,IsActive,AddedBy) VALUES(@N1,@N2,CONVERT(int,@I1),@N3,@N4,CONVERT(int,@I2),CONVERT(int,@BranchID),CONVERT(int,@FloorID),@SupervisorEmployeeID,@N5,CONVERT(date,@N6),@B1,@EmployeeID); ELSE UPDATE dbo.HK_StaffMaster SET StaffCode=@N1,StaffName=@N2,EmployeeID=CONVERT(int,@I1),MobileNumber=@N3,StaffType=@N4,VendorID=CONVERT(int,@I2),BranchID=CONVERT(int,@BranchID),FloorID=CONVERT(int,@FloorID),SupervisorID=@SupervisorEmployeeID,ShiftName=@N5,JoiningDate=CONVERT(date,@N6),IsActive=@B1,UpdatedBy=@EmployeeID,UpdatedDate=GETDATE() WHERE StaffID=@ID; END
 ELSE IF @Module='Activities'
 BEGIN SET @ID=ISNULL(@Payload.value('string((/Root/ActivityID)[1])','int'),0); SET @N1=@Payload.value('string((/Root/ActivityName)[1])','nvarchar(150)'); SET @N2=@Payload.value('string((/Root/ActivityCategory)[1])','nvarchar(80)'); SET @N3=NULLIF(@Payload.value('string((/Root/Description)[1])','nvarchar(1000)'),''); SET @N4=@Payload.value('string((/Root/Frequency)[1])','varchar(10)'); SET @I1=NULLIF(@Payload.value('string((/Root/EstimatedMinutes)[1])','varchar(20)'),''); SET @N5=@Payload.value('string((/Root/Priority)[1])','varchar(10)'); SET @B1=ISNULL(@Payload.value('string((/Root/RequiresInspection)[1])','bit'),0); SET @B2=ISNULL(@Payload.value('string((/Root/RequiresPhoto)[1])','bit'),0); IF @ID=0 INSERT dbo.HK_ActivityMaster(ActivityName,ActivityCategory,Description,Frequency,EstimatedMinutes,Priority,RequiresInspection,RequiresPhoto,AddedBy) VALUES(@N1,@N2,@N3,@N4,CONVERT(smallint,@I1),@N5,@B1,@B2,@EmployeeID); ELSE UPDATE dbo.HK_ActivityMaster SET ActivityName=@N1,ActivityCategory=@N2,Description=@N3,Frequency=@N4,EstimatedMinutes=CONVERT(smallint,@I1),Priority=@N5,RequiresInspection=@B1,RequiresPhoto=@B2,UpdatedBy=@EmployeeID,UpdatedDate=GETDATE() WHERE ActivityID=@ID; END
 ELSE IF @Module='Schedules'
 BEGIN SET @ID=ISNULL(@Payload.value('string((/Root/ScheduleID)[1])','int'),0); SET @I1=@Payload.value('string((/Root/ActivityID)[1])','int'); SET @BranchID=@Payload.value('string((/Root/BranchID)[1])','int'); SET @FloorID=@Payload.value('string((/Root/FloorID)[1])','int'); SET @I2=@Payload.value('string((/Root/StaffID)[1])','int'); SET @SupervisorEmployeeID=NULLIF(@Payload.value('string((/Root/SupervisorID)[1])','varchar(20)'),''); SET @N1=@Payload.value('string((/Root/ScheduleDate)[1])','varchar(10)'); SET @N2=@Payload.value('string((/Root/StartTime)[1])','varchar(8)'); SET @N3=@Payload.value('string((/Root/EndTime)[1])','varchar(8)'); SET @N4=@Payload.value('string((/Root/Frequency)[1])','varchar(10)'); SET @N5=@Payload.value('string((/Root/Priority)[1])','varchar(10)'); IF @SupervisorEmployeeID IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.EmployeeInfo WHERE EmployeeID=@SupervisorEmployeeID) RAISERROR('Select a valid supervisor.',16,1); IF NOT EXISTS(SELECT 1 FROM dbo.HK_FloorMaster WHERE FloorID=@FloorID AND BranchID=@BranchID) RAISERROR('The selected floor does not belong to the selected branch.',16,1); IF @ID=0 INSERT dbo.HK_ActivitySchedule(ActivityID,BranchID,FloorID,StaffID,SupervisorID,ScheduleDate,StartTime,EndTime,Frequency,Priority,AddedBy) VALUES(@I1,@BranchID,@FloorID,@I2,@SupervisorEmployeeID,CONVERT(date,@N1),CONVERT(time,@N2),CONVERT(time,@N3),@N4,@N5,@EmployeeID); ELSE UPDATE dbo.HK_ActivitySchedule SET ActivityID=@I1,BranchID=@BranchID,FloorID=@FloorID,StaffID=@I2,SupervisorID=@SupervisorEmployeeID,ScheduleDate=CONVERT(date,@N1),StartTime=CONVERT(time,@N2),EndTime=CONVERT(time,@N3),Frequency=@N4,Priority=@N5,UpdatedBy=@EmployeeID,UpdatedDate=GETDATE() WHERE ScheduleID=@ID; IF @ID=0 SET @ID=SCOPE_IDENTITY(); IF NOT EXISTS(SELECT 1 FROM dbo.HK_ActivityAssignment WHERE ScheduleID=@ID) INSERT dbo.HK_ActivityAssignment(ScheduleID,ActivityID,BranchID,FloorID,StaffID,VendorID,SupervisorID,ScheduledDate,ScheduledStart,ScheduledEnd,Status,AddedBy) SELECT sch.ScheduleID,sch.ActivityID,sch.BranchID,sch.FloorID,sch.StaffID,st.VendorID,sch.SupervisorID,sch.ScheduleDate,sch.StartTime,sch.EndTime,'Pending',@EmployeeID FROM dbo.HK_ActivitySchedule sch JOIN dbo.HK_StaffMaster st ON st.StaffID=sch.StaffID WHERE sch.ScheduleID=@ID; END
 ELSE IF @Module='Attendance'
 BEGIN SET @ID=ISNULL(@Payload.value('string((/Root/AttendanceID)[1])','int'),0); SET @I1=@Payload.value('string((/Root/StaffID)[1])','int'); SET @N1=@Payload.value('string((/Root/AttendanceDate)[1])','varchar(10)'); SET @N2=@Payload.value('string((/Root/ShiftName)[1])','nvarchar(50)'); SET @N3=@Payload.value('string((/Root/AttendanceStatus)[1])','varchar(15)'); SET @B1=ISNULL(@Payload.value('string((/Root/IsLate)[1])','bit'),0); SET @B2=ISNULL(@Payload.value('string((/Root/IsEarlyDeparture)[1])','bit'),0); SET @N4=NULLIF(@Payload.value('string((/Root/OvertimeHours)[1])','varchar(20)'),''); SET @N5=NULLIF(@Payload.value('string((/Root/Remarks)[1])','nvarchar(1000)'),''); IF @ID=0 BEGIN IF EXISTS(SELECT 1 FROM dbo.HK_StaffMaster WHERE StaffID=@I1) SELECT @BranchID=BranchID,@FloorID=FloorID,@I2=VendorID FROM dbo.HK_StaffMaster WHERE StaffID=@I1; INSERT dbo.HK_StaffAttendance(StaffID,AttendanceDate,VendorID,BranchID,FloorID,ShiftName,AttendanceStatus,IsLate,IsEarlyDeparture,OvertimeHours,Remarks,AddedBy) VALUES(@I1,CONVERT(date,@N1),@I2,@BranchID,@FloorID,@N2,@N3,@B1,@B2,ISNULL(CONVERT(decimal(6,2),@N4),0),@N5,@EmployeeID); END ELSE UPDATE dbo.HK_StaffAttendance SET AttendanceStatus=@N3,IsLate=@B1,IsEarlyDeparture=@B2,OvertimeHours=ISNULL(CONVERT(decimal(6,2),@N4),0),Remarks=@N5,UpdatedBy=@EmployeeID,UpdatedDate=GETDATE() WHERE AttendanceID=@ID; END
 ELSE IF @Module='DailyActivities' OR @Module='WeeklyMonthlyActivities'
 BEGIN SET @I1=@Payload.value('string((/Root/AssignmentID)[1])','int'); SET @N1=@Payload.value('string((/Root/Status)[1])','varchar(20)'); SET @N2=NULLIF(@Payload.value('string((/Root/Remarks)[1])','nvarchar(2000)'),''); UPDATE dbo.HK_ActivityAssignment SET Status=@N1,Remarks=@N2,ActualStart=CASE WHEN @N1='In Progress' AND ActualStart IS NULL THEN GETDATE() ELSE ActualStart END,ActualEnd=CASE WHEN @N1 IN('Completed','Verified') THEN GETDATE() ELSE ActualEnd END,UpdatedBy=@EmployeeID,UpdatedDate=GETDATE() WHERE AssignmentID=@I1; IF @@ROWCOUNT=0 RAISERROR('Task was not found.',16,1); INSERT dbo.HK_ActivityLog(AssignmentID,OldStatus,NewStatus,Remarks,ChangedBy) SELECT @I1,NULL,@N1,@N2,@EmployeeID; SET @ID=@I1; END
 ELSE IF @Module='Inspections'
 BEGIN SET @I1=@Payload.value('string((/Root/AssignmentID)[1])','int'); SET @I2=@Payload.value('string((/Root/CleanlinessRating)[1])','int'); SET @I3=@Payload.value('string((/Root/QualityRating)[1])','int'); SET @N1=@Payload.value('string((/Root/InspectionStatus)[1])','varchar(12)'); SET @B1=ISNULL(@Payload.value('string((/Root/ReworkRequired)[1])','bit'),0); SET @N2=NULLIF(@Payload.value('string((/Root/Remarks)[1])','nvarchar(2000)'),''); DECLARE @InspectedStaff int; SELECT @InspectedStaff=StaffID FROM dbo.HK_ActivityAssignment WHERE AssignmentID=@I1; IF @InspectedStaff IS NULL RAISERROR('Task was not found.',16,1); IF NOT EXISTS(SELECT 1 FROM dbo.EmployeeInfo WHERE EmployeeID=@EmployeeID) RAISERROR('Supervisor employee mapping was not found.',16,1); INSERT dbo.HK_Inspection(AssignmentID,StaffID,SupervisorID,CleanlinessRating,QualityRating,Remarks,InspectionStatus,ReworkRequired,AddedBy) VALUES(@I1,@InspectedStaff,@EmployeeID,@I2,@I3,@N2,@N1,@B1,@EmployeeID); UPDATE dbo.HK_ActivityAssignment SET Status=CASE WHEN @N1='Approved' THEN 'Verified' ELSE 'Rework Required' END,UpdatedBy=@EmployeeID,UpdatedDate=GETDATE() WHERE AssignmentID=@I1; END
 ELSE IF @Module='VendorPerformance'
 BEGIN
  DECLARE @EvalVendor int=@Payload.value('string((/Root/VendorID)[1])','int'),@EvalYear smallint=@Payload.value('string((/Root/EvaluationYear)[1])','smallint'),@EvalMonth tinyint=@Payload.value('string((/Root/EvaluationMonth)[1])','tinyint'),@Manpower decimal(5,2),@Completion decimal(5,2),@Quality decimal(5,2),@Sla decimal(5,2),@Complaints decimal(5,2),@Overall decimal(5,2),@Rating varchar(12);
  SELECT @Manpower=CASE WHEN v.ContractedManpower=0 THEN 0 ELSE 100.0*COUNT(s.StaffID)/v.ContractedManpower END FROM dbo.HK_VendorMaster v LEFT JOIN dbo.HK_StaffMaster s ON s.VendorID=v.VendorID AND s.IsActive=1 WHERE v.VendorID=@EvalVendor GROUP BY v.ContractedManpower;
  SELECT @Completion=ISNULL(100.0*SUM(CASE WHEN Status IN('Completed','Verified') THEN 1 ELSE 0 END)/NULLIF(COUNT(*),0),0),@Sla=ISNULL(100.0*SUM(CASE WHEN Status='Verified' AND (ActualEnd IS NULL OR ActualEnd<=DATEADD(day,1,ScheduledDate)) THEN 1 ELSE 0 END)/NULLIF(COUNT(*),0),0) FROM dbo.HK_ActivityAssignment WHERE VendorID=@EvalVendor AND YEAR(ScheduledDate)=@EvalYear AND MONTH(ScheduledDate)=@EvalMonth;
  SELECT @Quality=ISNULL(AVG(CONVERT(decimal(5,2),i.QualityRating))*20,0) FROM dbo.HK_Inspection i JOIN dbo.HK_ActivityAssignment a ON a.AssignmentID=i.AssignmentID WHERE a.VendorID=@EvalVendor AND YEAR(i.InspectionDate)=@EvalYear AND MONTH(i.InspectionDate)=@EvalMonth;
  SELECT @Complaints=ISNULL(100.0*SUM(CASE WHEN Status IN('Resolved','Closed') THEN 1 ELSE 0 END)/NULLIF(COUNT(*),0),0) FROM dbo.HK_Complaint WHERE VendorID=@EvalVendor AND YEAR(ComplaintDate)=@EvalYear AND MONTH(ComplaintDate)=@EvalMonth;
  SET @Manpower=ISNULL(@Manpower,0); SET @Completion=ISNULL(@Completion,0); SET @Quality=ISNULL(@Quality,0); SET @Sla=ISNULL(@Sla,0); SET @Complaints=ISNULL(@Complaints,0); SET @Overall=(@Manpower+@Completion+@Quality+@Sla+@Complaints)/5; SET @Rating=CASE WHEN @Overall>=90 THEN 'Excellent' WHEN @Overall>=75 THEN 'Good' WHEN @Overall>=60 THEN 'Satisfactory' ELSE 'Needs Improvement' END; SET @N1=NULLIF(@Payload.value('string((/Root/Remarks)[1])','nvarchar(2000)'),'');
  IF EXISTS(SELECT 1 FROM dbo.HK_VendorEvaluation WHERE VendorID=@EvalVendor AND EvaluationYear=@EvalYear AND EvaluationMonth=@EvalMonth) UPDATE dbo.HK_VendorEvaluation SET ManpowerScore=@Manpower,CompletionScore=@Completion,QualityScore=@Quality,SlaScore=@Sla,ComplaintScore=@Complaints,OverallScore=@Overall,Rating=@Rating,Remarks=@N1 WHERE VendorID=@EvalVendor AND EvaluationYear=@EvalYear AND EvaluationMonth=@EvalMonth;
  ELSE INSERT dbo.HK_VendorEvaluation(VendorID,EvaluationYear,EvaluationMonth,ManpowerScore,CompletionScore,QualityScore,SlaScore,ComplaintScore,OverallScore,Rating,Remarks,AddedBy) VALUES(@EvalVendor,@EvalYear,@EvalMonth,@Manpower,@Completion,@Quality,@Sla,@Complaints,@Overall,@Rating,@N1,@EmployeeID);
  SELECT @ID=EvaluationID FROM dbo.HK_VendorEvaluation WHERE VendorID=@EvalVendor AND EvaluationYear=@EvalYear AND EvaluationMonth=@EvalMonth;
 END
 ELSE IF @Module='Complaints'
 BEGIN SET @ID=ISNULL(@Payload.value('string((/Root/ComplaintID)[1])','int'),0); SET @BranchID=@Payload.value('string((/Root/BranchID)[1])','int'); SET @FloorID=NULLIF(@Payload.value('string((/Root/FloorID)[1])','varchar(20)'),''); SET @N1=@Payload.value('string((/Root/Category)[1])','nvarchar(80)'); SET @N2=@Payload.value('string((/Root/Description)[1])','nvarchar(2000)'); SET @N3=@Payload.value('string((/Root/Priority)[1])','varchar(10)'); SET @I1=NULLIF(@Payload.value('string((/Root/AssignedStaffID)[1])','varchar(20)'),''); SET @I2=NULLIF(@Payload.value('string((/Root/VendorID)[1])','varchar(20)'),''); SET @N4=NULLIF(@Payload.value('string((/Root/ExpectedResolution)[1])','varchar(30)'),''); SET @N5=NULLIF(@Payload.value('string((/Root/Status)[1])','varchar(15)'),''); SET @N6=NULLIF(@Payload.value('string((/Root/ResolutionRemarks)[1])','nvarchar(2000)'),''); IF @FloorID IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.HK_FloorMaster WHERE FloorID=CONVERT(int,@FloorID) AND BranchID=@BranchID) RAISERROR('The selected floor does not belong to the selected branch.',16,1); IF @ID=0 BEGIN INSERT dbo.HK_Complaint(BranchID,FloorID,Category,Description,Priority,AssignedStaffID,VendorID,ExpectedResolution,Status,ResolutionRemarks,AddedBy) VALUES(@BranchID,CONVERT(int,@FloorID),@N1,@N2,@N3,CONVERT(int,@I1),CONVERT(int,@I2),CONVERT(datetime,@N4,126),ISNULL(@N5,'Open'),@N6,@EmployeeID); SET @ID=SCOPE_IDENTITY(); END ELSE UPDATE dbo.HK_Complaint SET Status=ISNULL(@N5,Status),AssignedStaffID=CONVERT(int,@I1),ResolutionRemarks=@N6,UpdatedBy=@EmployeeID,UpdatedDate=GETDATE() WHERE ComplaintID=@ID; END
 ELSE IF @Module='Inventory'
 BEGIN SET @I1=@Payload.value('string((/Root/ConsumableID)[1])','int'); SET @N1=@Payload.value('string((/Root/TransactionType)[1])','varchar(6)'); SET @D1=@Payload.value('string((/Root/Quantity)[1])','decimal(12,2)'); SET @I2=NULLIF(@Payload.value('string((/Root/VendorID)[1])','varchar(20)'),''); SET @I3=NULLIF(@Payload.value('string((/Root/StaffID)[1])','varchar(20)'),''); SET @BranchID=NULLIF(@Payload.value('string((/Root/BranchID)[1])','varchar(20)'),''); SET @FloorID=NULLIF(@Payload.value('string((/Root/FloorID)[1])','varchar(20)'),''); SET @N2=NULLIF(@Payload.value('string((/Root/Remarks)[1])','nvarchar(1000)'),''); IF @FloorID IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.HK_FloorMaster WHERE FloorID=CONVERT(int,@FloorID) AND BranchID=CONVERT(int,@BranchID)) RAISERROR('The selected floor does not belong to the selected branch.',16,1); INSERT dbo.HK_ConsumableTransaction(ConsumableID,TransactionType,Quantity,VendorID,StaffID,BranchID,FloorID,Remarks,AddedBy) VALUES(@I1,@N1,@D1,CONVERT(int,@I2),CONVERT(int,@I3),CONVERT(int,@BranchID),CONVERT(int,@FloorID),@N2,@EmployeeID); SET @ID=SCOPE_IDENTITY(); END
 ELSE IF @Module='Consumables'
 BEGIN SET @ID=ISNULL(@Payload.value('string((/Root/ConsumableID)[1])','int'),0); SET @N1=@Payload.value('string((/Root/ItemCode)[1])','varchar(40)'); SET @N2=@Payload.value('string((/Root/ItemName)[1])','nvarchar(150)'); SET @N3=@Payload.value('string((/Root/UnitOfMeasure)[1])','nvarchar(30)'); SET @D1=@Payload.value('string((/Root/MinimumStock)[1])','decimal(12,2)'); SET @B1=ISNULL(@Payload.value('string((/Root/IsActive)[1])','bit'),1); IF @ID=0 INSERT dbo.HK_ConsumableMaster(ItemCode,ItemName,UnitOfMeasure,MinimumStock,IsActive,AddedBy) VALUES(@N1,@N2,@N3,@D1,@B1,@EmployeeID); ELSE UPDATE dbo.HK_ConsumableMaster SET ItemCode=@N1,ItemName=@N2,UnitOfMeasure=@N3,MinimumStock=@D1,IsActive=@B1,UpdatedBy=@EmployeeID,UpdatedDate=GETDATE() WHERE ConsumableID=@ID; END
 ELSE RAISERROR('This module does not support saving.',16,1);
 INSERT dbo.HK_AuditLog(EntityName,EntityID,ActionName,PerformedBy) VALUES(@Module,@ID,'Save',@EmployeeID);
 COMMIT TRANSACTION;
 END TRY BEGIN CATCH IF @@TRANCOUNT>0 ROLLBACK TRANSACTION; DECLARE @Error nvarchar(2048)=ERROR_MESSAGE(); RAISERROR(@Error,16,1); END CATCH
END
GO
IF OBJECT_ID('dbo.usp_HK_DeactivateModuleData','P') IS NOT NULL DROP PROCEDURE dbo.usp_HK_DeactivateModuleData;
GO
CREATE PROCEDURE dbo.usp_HK_DeactivateModuleData @Module varchar(40),@RecordID int,@EmployeeID int AS
BEGIN SET NOCOUNT ON;
 DECLARE @Table sysname=CASE @Module WHEN 'Floors' THEN 'HK_FloorMaster' WHEN 'Staff' THEN 'HK_StaffMaster' WHEN 'Vendors' THEN 'HK_VendorMaster' WHEN 'Activities' THEN 'HK_ActivityMaster' WHEN 'Schedules' THEN 'HK_ActivitySchedule' WHEN 'Consumables' THEN 'HK_ConsumableMaster' END;
 IF @Table IS NULL RAISERROR('This record cannot be deactivated.',16,1);
 DECLARE @IDColumn sysname=CASE @Module WHEN 'Floors' THEN 'FloorID' WHEN 'Staff' THEN 'StaffID' WHEN 'Vendors' THEN 'VendorID' WHEN 'Activities' THEN 'ActivityID' WHEN 'Schedules' THEN 'ScheduleID' WHEN 'Consumables' THEN 'ConsumableID' END;
 DECLARE @SQL nvarchar(500)=N'UPDATE dbo.'+QUOTENAME(@Table)+N' SET IsActive=0,UpdatedBy=@U,UpdatedDate=GETDATE() WHERE '+QUOTENAME(@IDColumn)+N'=@I';
 EXEC sys.sp_executesql @SQL,N'@U int,@I int',@U=@EmployeeID,@I=@RecordID;
 INSERT dbo.HK_AuditLog(EntityName,EntityID,ActionName,PerformedBy) VALUES(@Module,@RecordID,'Deactivate',@EmployeeID);
END
GO
